1: /**
2:  * Idempotent bootstrap seeding for US-01.
3:  *
4:  * Rules (see `.opencode/skills/strapi-multi-country/SKILL.md` §3 and
5:  * `specs/US-01-policyholder-vehicle-form.md` §3):
6:  * - natural key for `country-config` is `country`;
7:  * - natural key for `form-field` is `(country, key)`;
8:  * - an entry is only created when no draft AND no published version exists,
9:  *   so restarting the stack never duplicates or mutates business-edited rows;
10:  * - new entries are published immediately (`status: 'published'`).
11:  */
12: import type { Core } from '@strapi/strapi';
13: 
14: import {
15:   countryConfigSeeds,
16:   type CountryConfigSeed,
17:   formFieldSeeds,
18:   type FormFieldSeed,
19: } from './seed-data';
20: 
21: type SeedStatus = 'draft' | 'published';
22: 
23: interface SeedDocumentService<TData extends object> {
24:   findMany(params: {
25:     filters: Record<string, unknown>;
26:     status: SeedStatus;
27:   }): Promise<ReadonlyArray<unknown>>;
28:   create(params: { data: TData; status: SeedStatus }): Promise<unknown>;
29: }
30: 
31: /**
32:  * Narrow, typed view over the Strapi 5 Document Service.
33:  *
34:  * The cast keeps the bootstrap independent from generated content-type typings
35:  * (`types/generated/contentTypes.d.ts`); payloads are still validated by the
36:  * Document Service itself at runtime.
37:  */
38: const documentService = <TData extends object>(
39:   strapi: Core.Strapi,
40:   uid: string
41: ): SeedDocumentService<TData> =>
42:   strapi.documents(uid as never) as unknown as SeedDocumentService<TData>;
43: 
44: const existsWithStatus = async <TData extends object>(
45:   documents: SeedDocumentService<TData>,
46:   filters: Record<string, unknown>,
47:   status: SeedStatus
48: ): Promise<boolean> => {
49:   const entries = await documents.findMany({ filters, status });
50:   return entries.length > 0;
51: };
52: 
53: /**
54:  * `findMany` defaults to the draft version in Strapi 5, so both statuses are
55:  * queried explicitly: a published document still has a draft counterpart, but
56:  * checking both guarantees an unpublished hand-made entry is never duplicated.
57:  */
58: const entryExists = async <TData extends object>(
59:   documents: SeedDocumentService<TData>,
60:   filters: Record<string, unknown>
61: ): Promise<boolean> => {
62:   if (await existsWithStatus(documents, filters, 'draft')) {
63:     return true;
64:   }
65: 
66:   return existsWithStatus(documents, filters, 'published');
67: };
68: 
69: const seedCountryConfigs = async (strapi: Core.Strapi): Promise<void> => {
70:   const documents = documentService<CountryConfigSeed>(
71:     strapi,
72:     'api::country-config.country-config'
73:   );
74: 
75:   for (const config of countryConfigSeeds) {
76:     const exists = await entryExists(documents, { country: config.country });
77: 
78:     if (exists) {
79:       continue;
80:     }
81: 
82:     await documents.create({ data: config, status: 'published' });
83:     strapi.log.info(`[bootstrap] Seeded country-config for ${config.country}.`);
84:   }
85: };
86: 
87: const seedFormFields = async (strapi: Core.Strapi): Promise<void> => {
88:   const documents = documentService<FormFieldSeed>(strapi, 'api::form-field.form-field');
89: 
90:   for (const field of formFieldSeeds) {
91:     const exists = await entryExists(documents, {
92:       country: field.country,
93:       key: field.key,
94:     });
95: 
96:     if (exists) {
97:       continue;
98:     }
99: 
100:     await documents.create({ data: field, status: 'published' });
101:     strapi.log.info(`[bootstrap] Seeded form-field ${field.country}/${field.key}.`);
102:   }
103: };
104: 
105: export const seedContent = async (strapi: Core.Strapi): Promise<void> => {
106:   await seedCountryConfigs(strapi);
107:   await seedFormFields(strapi);
108: 
109:   strapi.log.info(
110:     `[bootstrap] Seed verified: ${countryConfigSeeds.length} country configs and ${formFieldSeeds.length} form fields for CO/CL.`
111:   );
112: };

