1: /**
2:  * Programmatic Public-role hardening (ADR-002, US-01 §4.5).
3:  *
4:  * The Angular application is fully anonymous and read-only: it never sends an
5:  * `Authorization` header and no API token exists. The only browser access path
6:  * is therefore the users-permissions `Public` role, which must keep exactly the
7:  * read-only actions listed below and nothing else.
8:  *
9:  * The configuration is a full replacement, not an addition: any other
10:  * permission attached to `Public` (including `api::*`, `plugin::users-permissions.*`
11:  * and `plugin::upload.*` entries) is revoked, so the default is denial.
12:  */
13: import type { Core } from '@strapi/strapi';
14: 
15: export const PUBLIC_READ_ACTIONS = [
16:   'api::form-field.form-field.find',
17:   'api::form-field.form-field.findOne',
18:   'api::country-config.country-config.find',
19:   'api::country-config.country-config.findOne',
20: ] as const;
21: 
22: interface RoleRecord {
23:   readonly id: number;
24:   readonly type: string | null;
25: }
26: 
27: interface PermissionRecord {
28:   readonly id: number;
29:   readonly action: string;
30: }
31: 
32: const PUBLIC_ROLE_TYPE = 'public';
33: 
34: export const configurePublicRolePermissions = async (strapi: Core.Strapi): Promise<void> => {
35:   const publicRole = (await strapi.db.query('plugin::users-permissions.role').findOne({
36:     where: { type: PUBLIC_ROLE_TYPE },
37:   })) as RoleRecord | null;
38: 
39:   if (!publicRole) {
40:     // Fail closed: without the Public role the read-only posture cannot be verified.
41:     throw new Error(
42:       '[bootstrap] users-permissions Public role was not found; refusing to start with an unverified permission set.'
43:     );
44:   }
45: 
46:   const permissionStore = strapi.db.query('plugin::users-permissions.permission');
47: 
48:   const currentPermissions = (await permissionStore.findMany({
49:     where: { role: { id: publicRole.id } },
50:   })) as PermissionRecord[];
51: 
52:   const allowlist = new Set<string>(PUBLIC_READ_ACTIONS);
53:   const keptActions = new Set<string>();
54:   const permissionsToRevoke: PermissionRecord[] = [];
55: 
56:   for (const permission of currentPermissions) {
57:     // Keep the first record per allowed action; revoke everything else,
58:     // including duplicates of an allowed action.
59:     if (!allowlist.has(permission.action) || keptActions.has(permission.action)) {
60:       permissionsToRevoke.push(permission);
61:       continue;
62:     }
63: 
64:     keptActions.add(permission.action);
65:   }
66: 
67:   for (const permission of permissionsToRevoke) {
68:     await permissionStore.delete({ where: { id: permission.id } });
69:   }
70: 
71:   const permissionsToGrant = PUBLIC_READ_ACTIONS.filter((action) => !keptActions.has(action));
72: 
73:   for (const action of permissionsToGrant) {
74:     await permissionStore.create({ data: { action, role: publicRole.id } });
75:   }
76: 
77:   strapi.log.info(
78:     `[bootstrap] Public role locked to ${PUBLIC_READ_ACTIONS.length} read-only actions ` +
79:       `(revoked: ${permissionsToRevoke.length}, granted: ${permissionsToGrant.length}).`
80:   );
81: };

