14: /** Reads the country exclusively from the router; no root `ActivatedRoute` injection. */
15: @Injectable({ providedIn: 'root' })
16: export class CountryContextService {
17:   private readonly router = inject(Router);
18: 
19:   private readonly routeContext = signal<RouteContext>(this.readFromRouter());
20: 
21:   readonly country = computed<CountryCode>(() => this.routeContext().country);
22:   readonly currentStep = computed<WizardStep>(() => this.routeContext().step);
23:   readonly entry = computed(() => COUNTRY_CATALOG_BY_CODE[this.country()]);
24:   readonly locale = computed<AppLocale>(() => this.entry().locale);
25:   readonly currency = computed<CurrencyCode>(() => this.entry().currency);
26: 
27:   constructor() {
28:     this.router.events
29:       .pipe(
30:         filter((event): event is NavigationEnd => event instanceof NavigationEnd),
31:         takeUntilDestroyed(),
32:       )
33:       .subscribe(() => this.routeContext.set(this.readFromRouter()));
34:   }
35: 
36:   /** Single place where internal wizard links are built (ADR-001 §4.2). */
37:   quotePath(step: 'quote' | 'plans' = 'quote'): string {
38:     const segment = this.entry().routeSegment;
39:     return step === 'plans' ? `/${segment}/quote/plans` : `/${segment}/quote`;
40:   }
41: 
42:   pathFor(country: CountryCode, step: 'quote' | 'plans' = 'quote'): string {
43:     const segment = COUNTRY_CATALOG_BY_CODE[country].routeSegment;
44:     return step === 'plans' ? `/${segment}/quote/plans` : `/${segment}/quote`;
45:   }
46: 
47:   private readFromRouter(): RouteContext {
48:     const snapshot = this.router.routerState.snapshot.root;
49:     return {
50:       country: readCountryFromSnapshot(snapshot),
51:       step: this.router.url.split('?')[0].includes('/plans') ? 'plans' : 'policyholder',
52:     };
53:   }
54: }
55: 
56: /** Walks down `firstChild` snapshots so this service works at the root injector. */
57: export function readCountryFromSnapshot(snapshot: ActivatedRouteSnapshot): CountryCode {
58:   let current: ActivatedRouteSnapshot = snapshot;
59:   while (current.firstChild) {
60:     current = current.firstChild;
61:   }
62:   return toCountryCode(current.paramMap.get('country'));
63: }

