36: /** The only place that builds Strapi URLs and appends the country filter. */
37: @Injectable({ providedIn: 'root' })
38: export class CatalogueApi {
39:   private readonly http = inject(HttpClient);
40:   private readonly apiBaseUrl = inject(API_BASE_URL);
41: 
42:   getFormFields(country: CountryCode): Observable<readonly FormFieldConfig[]> {
43:     const url =
44:       `${this.apiBaseUrl}/api/form-fields?filters[country][$eq]=${country}` +
45:       '&sort=order:asc&pagination[pageSize]=100';
46: 
47:     return this.http
48:       .get<StrapiListResponse<unknown>>(url)
49:       .pipe(map((response) => this.mapFields(response, country)));
50:   }
51: 
52:   getCountryConfig(country: CountryCode): Observable<CountryConfig | null> {
53:     const url = `${this.apiBaseUrl}/api/country-configs?filters[country][$eq]=${country}`;
54:     return this.http
55:       .get<StrapiListResponse<unknown>>(url)
56:       .pipe(map((response) => this.mapCountryConfig(response, country)));
57:   }
58: 
59:   private mapFields(
60:     response: StrapiListResponse<unknown>,
61:     country: CountryCode,
62:   ): readonly FormFieldConfig[] {
63:     const rows = Array.isArray(response.data) ? response.data : [];
64:     const pagination = response.meta?.pagination;
65:     if (pagination && pagination.total > rows.length && isDevMode()) {
66:       console.warn(
67:         `[catalogue] only ${rows.length} of ${pagination.total} fields for ${country} were received (page size 100).`,
68:       );
69:     }
70: 
71:     const mapped: FormFieldConfig[] = [];
72:     for (const row of rows) {
73:       const field = this.toFormFieldConfig(row, country);
74:       if (field) {
75:         mapped.push(field);
76:       }
77:     }
78: 
79:     // De-duplicate by key keeping the lowest id, then apply the rendering order.
80:     mapped.sort((left, right) => left.key.localeCompare(right.key) || left.id - right.id);
81:     const byKey = new Map<string, FormFieldConfig>();
82:     for (const field of mapped) {
83:       const existing = byKey.get(field.key);
84:       if (existing && existing.id !== field.id && isDevMode()) {
85:         console.warn(`[catalogue] duplicate field key "${field.key}"; keeping id ${existing.id}.`);
86:       }
87:       if (!existing) {
88:         byKey.set(field.key, field);
89:       }
90:     }
91: 
92:     return [...byKey.values()].sort((left, right) => left.order - right.order || left.id - right.id);
93:   }
94: 
95:   private toFormFieldConfig(raw: unknown, country: CountryCode): FormFieldConfig | null {
96:     if (!isRecord(raw)) {
97:       this.warnInvalid('non-object row');
98:       return null;
99:     }
100: 
101:     const id = raw['id'];
102:     const documentId = raw['documentId'];
103:     const key = raw['key'];
104:     const label = raw['label'];
105:     const type = raw['type'];
106:     const required = raw['required'];
107:     const order = raw['order'];
108:     const section = raw['section'];
109:     const rowCountry = raw['country'];
110: 
111:     if (
112:       typeof id !== 'number' ||
113:       typeof documentId !== 'string' ||
114:       typeof key !== 'string' ||
